SELECT

FROM runtime_resource_bindings
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND resource_type = #{resourceType}
AND oma_external_id = #{omaExternalID}
AND state != 'deleted'

SELECT

FROM runtime_resource_bindings
WHERE runtime_profile_uuid = #{runtimeProfileUUID}
AND resource_type = #{resourceType}
AND remote_id = #{remoteID}
AND state != 'deleted'

SELECT

FROM runtime_resource_bindings

    organization_uuid = #{query.OrganizationUUID}
    AND workspace_uuid = #{query.WorkspaceUUID}
    AND resource_type = #{query.ResourceType}


            AND state IN ('active', 'archived')


            AND state = 'active'



        AND parent_oma_external_id = #{query.ParentOMAExternalID}


        AND resource_role = #{query.ResourceRole}


ORDER BY created_at DESC, id DESC
LIMIT #{query.Limit}
OFFSET #{query.Offset}

SELECT

FROM runtime_resource_bindings

    organization_uuid = #{query.OrganizationUUID}
    AND workspace_uuid = #{query.WorkspaceUUID}
    AND resource_type = #{query.ResourceType}


            AND state IN ('active', 'archived')


            AND state = 'active'


    AND (
        COALESCE(summary->>'name', '') ILIKE #{query.Pattern} ESCAPE '\'
        OR COALESCE(summary->>'title', '') ILIKE #{query.Pattern} ESCAPE '\'
        OR oma_external_id ILIKE #{query.Pattern} ESCAPE '\'
    )

ORDER BY created_at DESC, id DESC
LIMIT #{query.Limit}
OFFSET #{query.Offset}

mapper.update:
UPDATE runtime_resource_bindings
SET summary = CAST(#{params.Summary} AS jsonb),

        state = #{params.State},

    updated_at = NOW()
WHERE organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND resource_type = #{params.ResourceType}
AND oma_external_id = #{params.OMAExternalID}
AND state != 'deleted'
RETURNING

UPDATE runtime_resource_bindings
SET state = 'deleted',
    updated_at = NOW()
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND resource_type = #{resourceType}
AND oma_external_id = #{omaExternalID}
AND state != 'deleted'

